export class CacheManager { constructor(){this.map=new Map()} set(key,value,ttl=0){this.delete(key);const expires=ttl>0?Date.now()+ttl:0;const timer=ttl>0?setTimeout(()=>this.delete(key),ttl):null;this.map.set(key,{value,expires,timer});return value} get(key){const x=this.map.get(key);if(!x)return undefined;if(x.expires&&x.expires<=Date.now()){this.delete(key);return undefined}return x.value} has(key){return this.get(key)!==undefined} delete(key){const x=this.map.get(key);if(x?.timer)clearTimeout(x.timer);return this.map.delete(key)} clear(){for(const k of this.map.keys())this.delete(k)} }
export const cache=new CacheManager();